import pyomo.environ as pyo

DATA = {
    "departments": ["X", "Y", "Z"],
    "cost": {"X": 50, "Y": 80, "Z": 30},
    "min_hires": {"X": 20, "Y": 15, "Z": 10},
    "total_employees": 100,
}


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    model.D = pyo.Set(initialize=d["departments"])

    def cost_rule(m, i):
        return d["cost"][i]

    # x[i]: number of new hires assigned to department i (whole people)
    model.x = pyo.Var(
        model.D, within=pyo.NonNegativeIntegers
    )

    # Objective: minimize total training cost
    def obj_rule(m):
        return sum(d["cost"][i] * m.x[i] for i in m.D)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    # All hundred new employees must be allocated exactly
    def total_rule(m):
        return sum(m.x[i] for i in m.D) == d["total_employees"]

    model.total_alloc = pyo.Constraint(rule=total_rule)

    # Each department's minimum staffing requirement (>=)
    def min_rule(m, i):
        return m.x[i] >= d["min_hires"][i]

    model.min_hires = pyo.Constraint(model.D, rule=min_rule)

    return model

import pyomo.environ as pyo

DATA = {
    "departments": ["X", "Y", "Z"],
    "total_hires": 100,
    "min_hires": {"X": 20, "Y": 15, "Z": 10},
    "train_cost": {"X": 50, "Y": 80, "Z": 30},
}

def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    model.D = pyo.Set(initialize=d["departments"])

    def lb_rule(m, i):
        return d["min_hires"][i]

    model.x = pyo.Var(
        model.D,
        domain=pyo.NonNegativeIntegers,
        bounds=lambda m, i: (d["min_hires"][i], None),
    )

    def obj_rule(m):
        return sum(d["train_cost"][i] * m.x[i] for i in m.D)

    model.obj = pyo.Objective(expr=obj_rule, sense=pyo.minimize)

    # Total number of new hires must equal 100
    def total_rule(m):
        return sum(m.x[i] for i in m.D) == d["total_hires"]

    model.total = pyo.Constraint(rule=total_rule)

    # Each department meets its minimum requirement (lower bounds above)
    def min_rule(m, i):
        return m.x[i] >= d["min_hires"][i]  # "at least" requirement

    model.min_hires = pyo.Constraint(model.D, rule=min_rule)

    return model
